warp:
shader_body {
          vec2 z=(uv-0.5)*2.0; vec2 c=vec2(-0.72,0.18+0.03*sin(time*0.3));
          float orbit=0.0;
          for(int i=0;i<12;i++){ z=vec2(z.x*z.x-z.y*z.y,2.0*z.x*z.y)+c;
            orbit+=exp(-dot(z,z)); if(dot(z,z)>16.0) break; }
          vec2 bend=0.022*vec2(sin(orbit*4.0),cos(orbit*3.0));
          ret=texture2D(sampler_main,uv+bend).rgb*0.97;
        }
